<?php
use ACL\AgentRooms\Models\RoomEvent;use ACL\AgentRooms\Repositories\AgentRepository;use ACL\AgentRooms\Repositories\EventRepository;use ACL\AgentRooms\Repositories\JobRepository;use ACL\AgentRooms\Repositories\MessageRepository;use ACL\AgentRooms\Repositories\RoomRepository;use ACL\AgentRooms\Rest\CommandsController;use ACL\AgentRooms\Rest\MessagesController;use ACL\AgentRooms\Services\AccessService;use ACL\AgentRooms\Services\AgentRuntime;use ACL\AgentRooms\Services\CoinFlipService;use ACL\AgentRooms\Services\CommandParser;use ACL\AgentRooms\Services\CommandRegistry;use ACL\AgentRooms\Services\CommandService;use ACL\AgentRooms\Services\DiceService;use ACL\AgentRooms\Services\EventProjectionService;use ACL\AgentRooms\Services\EventSyncService;use ACL\AgentRooms\Services\EventVisibilityService;use ACL\AgentRooms\Services\MessageInteractionPolicy;use ACL\AgentRooms\Services\ReadStateService;use ACL\AgentRooms\Services\RoomActionService;use ACL\AgentRooms\Services\RoomEventService;use ACL\AgentRooms\Services\WhisperRecipientResolver;use ACL\AgentRooms\Services\WhisperService;
class ACL_AR_Phase7CommandTest extends ACL_AR_TestCase{
	private RoomRepository $rooms;private EventRepository $events;private AccessService $access;private int $owner=0,$recipient=0,$third=0,$duplicate_name=0,$outsider=0,$room=0;private string $prefix='';
	public function run():void{$this->prefix='phase7-'.gmdate('YmdHis').'-'.wp_generate_password(5,false,false);$this->rooms=new RoomRepository();$this->events=new EventRepository();$this->access=new AccessService($this->rooms);$this->setup();try{$this->version_contract();$this->pass('phase7_version_contract');$this->registry_parser();$this->pass('phase7_registry_parser');$this->room_play();$this->pass('phase7_room_play');$this->whispers();$this->pass('phase7_whispers');$this->privacy();$this->pass('phase7_privacy');$this->routes_legacy_delete();$this->pass('phase7_routes_legacy_delete');}finally{$this->cleanup();}}
	private function user(string $suffix,string $name):int{$id=wp_insert_user(array('user_login'=>$this->prefix.'-'.$suffix,'user_pass'=>wp_generate_password(20),'user_email'=>$this->prefix.'-'.$suffix.'@example.test','display_name'=>$name,'role'=>'subscriber'));if(is_wp_error($id)){throw new RuntimeException($id->get_error_message());}get_user_by('id',$id)->add_cap('acl_ar_use_rooms');return(int)$id;}
	private function setup():void{$this->owner=$this->user('owner','P7 Owner');$this->recipient=$this->user('recipient','P7 Recipient');$this->third=$this->user('third','P7 Third');$this->duplicate_name=$this->user('duplicate','P7 Recipient');$this->outsider=$this->user('outsider','P7 Outsider');get_user_by('id',$this->owner)->add_cap('acl_ar_manage_own_rooms');wp_set_current_user($this->owner);$this->room=$this->rooms->create(array('title'=>$this->prefix,'slug'=>$this->prefix,'owner_user_id'=>$this->owner,'type'=>'private','visibility'=>'private','agent_reply_mode'=>'manual'));$this->rooms->add_member($this->room,$this->recipient);$this->rooms->add_member($this->room,$this->third);}
	private function version_contract():void{global$wpdb;$before=$wpdb->get_col("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA='".esc_sql(DB_NAME)."' AND TABLE_NAME LIKE 'wp_acl_ar_%' ORDER BY TABLE_NAME");\ACL\AgentRooms\Installer::install();\ACL\AgentRooms\Installer::install();$after=$wpdb->get_col("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA='".esc_sql(DB_NAME)."' AND TABLE_NAME LIKE 'wp_acl_ar_%' ORDER BY TABLE_NAME");$this->assert_same('1.5.6',ACL_AR_VERSION,'Plugin version wrong.');$this->assert_same('1.4.1',ACL_AR_DB_VERSION,'DB version wrong.');$this->assert_same('1.4.1',(string)get_option('acl_ar_db_version'),'Stored version wrong.');$this->assert_same($before,$after,'Schema changed.');foreach(array('action','dice_roll','coin_flip','whisper','presence_change','moderation','message_delete')as$type){$this->assert_true(in_array($type,RoomEvent::EVENT_TYPES,true),'Missing '.$type);}}
	private function registry_parser():void{$registry=new CommandRegistry();$defs=$registry->all();foreach(array('help','agents','ask','roll','coin','me','whisper')as$name){$this->assert_true(isset($defs[$name]),'Missing '.$name);}$this->assert_same('whisper',$registry->resolve('w')['name'],'Alias failed.');$this->assert_true($defs['ask']['can_cost'],'Ask cost flag.');$this->assert_true($defs['ask']['invokes_agent'],'Ask invoke flag.');$this->assert_true(!$defs['roll']['can_cost'],'Roll cost flag.');$p=(new CommandParser())->parse(" /ROLL 2d6+3\r\n");$this->assert_same('roll',$p['name'],'Normalize failed.');$this->assert_same('2d6+3',$p['arguments'],'Arguments failed.');$this->assert_wp_error((new CommandParser())->parse('hello'),'Plain parsed.');$this->assert_wp_error((new CommandParser())->parse('/'),'Empty accepted.');$q=(new CommandParser())->whisper_arguments('"P7 Recipient" hello there');$this->assert_same('P7 Recipient',$q['recipient'],'Quote name.');$this->assert_same('hello there',$q['message'],'Quote message.');$this->assert_wp_error((new CommandParser())->whisper_arguments('recipient'),'No message accepted.');$this->assert_wp_error((new CommandService($this->rooms,$this->access,$this->events))->execute($this->room,$this->owner,'/unknown','p7-unknown'),'Unknown accepted.');}
	private function room_play():void{$dice=new DiceService($this->events);foreach(array(''=>array(1,20,0),'d20'=>array(1,20,0),'1d20'=>array(1,20,0),'2d6+3'=>array(2,6,3),'2d6-1'=>array(2,6,-1))as$n=>$want){$s=$dice->parse($n);$this->assert_same($want[0],$s['count'],'Count.');$this->assert_same($want[1],$s['sides'],'Sides.');$this->assert_same($want[2],$s['modifier'],'Modifier.');}foreach(array('0d6','21d6','1d1','1d1001','1d6+10001','bad')as$bad){$this->assert_wp_error($dice->parse($bad),'Bad dice '.$bad);}$roll=$dice->roll($this->room,$this->owner,'2d6+3','p7-dice');$m=$roll['event']['metadata'];$this->assert_same('dice_roll',$roll['event']['event_type'],'Dice type.');$this->assert_same(2,count($m['rolls']),'Roll count.');foreach($m['rolls']as$v){$this->assert_true($v>=1&&$v<=6,'Bounds.');}$this->assert_same(array_sum($m['rolls']),$m['subtotal'],'Subtotal.');$this->assert_same($m['subtotal']+3,$m['total'],'Total.');$dup=$dice->roll($this->room,$this->owner,'d100','p7-dice');$this->assert_true($dup['duplicate'],'Dice duplicate.');$this->assert_same($roll['event']['id'],$dup['event']['id'],'Dice reroll.');$this->assert_same($m['rolls'],$dup['event']['metadata']['rolls'],'Roll changed.');$coin=new CoinFlipService($this->events);$flip=$coin->flip($this->room,$this->owner,'p7-coin');$this->assert_true(in_array($flip['event']['metadata']['result'],array('heads','tails'),true),'Coin result.');$flip2=$coin->flip($this->room,$this->owner,'p7-coin');$this->assert_true($flip2['duplicate'],'Coin duplicate.');$this->assert_same($flip['event']['id'],$flip2['event']['id'],'Coin changed.');$this->assert_wp_error((new CommandService($this->rooms,$this->access,$this->events))->execute($this->room,$this->owner,'/coin heads','p7-select'),'Selected coin.');$actions=new RoomActionService($this->events);$this->assert_wp_error($actions->create($this->room,$this->owner,'','p7-empty'),'Empty action.');$a=$actions->create($this->room,$this->owner,' moves closer ','p7-action');$this->assert_same('action',$a['event']['event_type'],'Action type.');$this->assert_same('moves closer',$a['event']['content'],'Action text.');$this->assert_same($a['event']['id'],$actions->create($this->room,$this->owner,'different','p7-action')['event']['id'],'Action duplicate.');}
	private function whispers():void{$resolver=new WhisperRecipientResolver($this->rooms,$this->access,$this->events);$eligible=$resolver->eligible($this->room,$this->owner);$this->assert_true(isset($eligible[$this->recipient]),'Recipient missing.');$this->assert_true(isset($eligible[$this->third]),'Third missing.');$this->assert_true(!isset($eligible[$this->owner]),'Self eligible.');$this->assert_true(!isset($eligible[$this->outsider]),'Outsider eligible.');$this->assert_same($this->recipient,$resolver->resolve($this->room,$this->owner,$this->recipient),'Canonical failed.');$this->assert_wp_error($resolver->resolve($this->room,$this->owner,$this->owner),'Self accepted.');$this->assert_wp_error($resolver->resolve($this->room,$this->owner,$this->outsider),'Outsider accepted.');$this->assert_same($this->recipient,$resolver->resolve($this->room,$this->owner,0,'p7 recipient'),'Exact match.');$this->rooms->add_member($this->room,$this->duplicate_name);$this->assert_wp_error($resolver->resolve($this->room,$this->owner,0,'P7 Recipient'),'Ambiguous accepted.');$service=new WhisperService($this->events,$resolver);$sent=$service->send($this->room,$this->owner,$this->recipient,'','private hello','p7-whisper');$e=$sent['event'];$this->assert_same('whisper',$e['event_type'],'Whisper type.');$this->assert_same('user',$e['audience_type'],'Audience type.');$this->assert_same($this->recipient,$e['audience_id'],'Audience ID.');$this->assert_same($this->owner,$e['actor_id'],'Actor.');$this->assert_same(array(),$e['metadata'],'Metadata.');$dup=$service->send($this->room,$this->owner,$this->recipient,'','changed','p7-whisper');$this->assert_true($dup['duplicate'],'Whisper duplicate.');$this->assert_same($e['id'],$dup['event']['id'],'Whisper duplicated.');$v=new EventVisibilityService($this->access);$this->assert_true($v->can_view($e,$this->owner,false),'Sender hidden.');$this->assert_true($v->can_view($e,$this->recipient,false),'Recipient hidden.');$this->assert_true(!$v->can_view($e,$this->third,false),'Third sees whisper.');$this->assert_true($v->can_view($e,$this->owner,true),'Manager hidden.');$projection=new EventProjectionService(null,$this->events);$out=$projection->project_page(array($e),false,$this->owner)[0];$in=$projection->project_page(array($e),false,$this->recipient)[0];$this->assert_same('outgoing',$out['whisper']['direction'],'Outgoing.');$this->assert_same($this->recipient,$out['whisper']['counterpart']['id'],'Outgoing counterpart.');$this->assert_same('incoming',$in['whisper']['direction'],'Incoming.');$this->assert_same($this->owner,$in['whisper']['counterpart']['id'],'Incoming counterpart.');$json=wp_json_encode(array($out,$in));$this->assert_true(false===stripos($json,'@example.test'),'Email leak.');$this->assert_true(false===strpos($json,$this->prefix.'-recipient'),'Login leak.');$policy=new MessageInteractionPolicy($this->rooms,$this->access,$this->events);foreach(array('reply','reaction','edit')as$action){$this->assert_wp_error($policy->target($this->room,$e['id'],$this->owner,$action),'Whisper interaction '.$action);}}
	private function privacy():void{$all=$this->events->scan_room_after($this->room,0,500);$whispers=array_values(array_filter($all,static fn($e)=>'whisper'===$e['event_type']));$w=end($whispers);$sync=new EventSyncService($this->events,new EventVisibilityService($this->access));$owner=$sync->page($this->room,$this->owner,false,'initial',0,50);$recipient=$sync->page($this->room,$this->recipient,false,'initial',0,50);$third=$sync->page($this->room,$this->third,false,'initial',0,50);$ids=static fn($p)=>array_map(static fn($e)=>(int)$e['id'],$p['events']);$this->assert_true(in_array((int)$w['id'],$ids($owner),true),'Sender stream.');$this->assert_true(in_array((int)$w['id'],$ids($recipient),true),'Recipient stream.');$this->assert_true(!in_array((int)$w['id'],$ids($third),true),'Third stream leak.');$this->assert_true((int)$third['latest_visible_event_id']!==(int)$w['id'],'Latest leak.');$this->assert_true(null===$third['paging']['before_cursor']||is_string($third['paging']['before_cursor']),'Paging invalid.');$reads=new ReadStateService($this->events,null,$this->rooms,$this->access);$rs=$reads->state($this->room,$this->recipient);$os=$reads->state($this->room,$this->owner);$ts=$reads->state($this->room,$this->third);$this->assert_true($rs['unread_count']>=1,'Incoming unread.');$this->assert_true($os['unread_count']>=0,'Sender unread invalid.');$this->assert_true($ts['first_unread_event_id']!==(int)$w['id'],'Third unread leak.');$advanced=$reads->advance($this->room,$this->recipient,(int)$w['id']);$this->assert_same((int)$w['id'],$advanced['last_read_event_id'],'Read advance.');$this->assert_same((int)$w['id'],$reads->advance($this->room,$this->recipient,0)['last_read_event_id'],'Read backward.');}
	private function routes_legacy_delete():void{global$wpdb;(new CommandsController(new CommandService($this->rooms,$this->access,$this->events)))->register_routes();$routes=rest_get_server()->get_routes();$this->assert_true(isset($routes['/acl-agent-rooms/v1/rooms/(?P<id>[\d]+)/commands']),'Route missing.');$this->assert_true(isset($routes['/acl-agent-rooms/v1/commands']),'Definitions missing.');wp_set_current_user($this->owner);$bad=new WP_REST_Request('POST','/');$bad->set_param('id',$this->room);$this->assert_wp_error((new CommandsController())->permissions($bad),'Nonce missing accepted.');$agents=new AgentRepository();$messages=new MessageRepository();$jobs=new JobRepository();$legacy=new MessagesController($this->rooms,$agents,$messages,$jobs,$this->access,new AgentRuntime($jobs,$this->rooms,$agents,$messages));$before=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.$wpdb->prefix.'acl_ar_messages WHERE room_id=%d',$this->room));$r=new WP_REST_Request('POST','/');$r->set_param('id',$this->room);$r->set_param('content','/roll d6');$r->set_param('client_request_id','p7-legacy-roll');$response=$legacy->create($r);$this->assert_true($response instanceof WP_REST_Response,'Legacy failed.');$this->assert_same(200,$response->get_status(),'Legacy status.');$after=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.$wpdb->prefix.'acl_ar_messages WHERE room_id=%d',$this->room));$this->assert_same($before,$after,'Command stored message.');$this->assert_same($response->get_data()['command']['event_id'],$legacy->create($r)->get_data()['command']['event_id'],'Legacy duplicate.');$temp=$this->rooms->create(array('title'=>$this->prefix.'-delete','slug'=>$this->prefix.'-delete','owner_user_id'=>$this->owner,'type'=>'private','visibility'=>'private'));$event=(new RoomActionService($this->events))->create($temp,$this->owner,'delete','p7-delete')['event'];$this->assert_true((bool)$this->events->find($event['id']),'Delete fixture.');$this->assert_true(true===$this->rooms->delete($temp),'Delete failed.');$this->assert_true(null===$this->events->find($event['id']),'Event survived delete.');}
	private function pass(string $n):void{echo'PASS '.$n.PHP_EOL;}private function cleanup():void{global$wpdb;wp_set_current_user($this->owner);if($this->room&&$this->rooms->find($this->room)){$wpdb->delete($wpdb->prefix.'acl_ar_usage',array('room_id'=>$this->room));$this->rooms->delete($this->room);}foreach(array($this->owner,$this->recipient,$this->third,$this->duplicate_name,$this->outsider)as$id){if($id){wp_delete_user($id);}}wp_set_current_user(0);}
}
